  window.InteractiveTable.Icons = {
    get(name, size = 16, extraClass = '') {
      const inner = svgData[name];
      if (!inner) {
        console.warn('Icon not found:', name);
        return '';
      }
      return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" class="huge-icon ${extraClass}" style="flex-shrink: 0; display: inline-block; vertical-align: middle;">${inner}</svg>`;
    },
    has(name) {
      return !!svgData[name];
    }
  };
